fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>> {
    let n = s.len();
    let mut result = Vec::with_capacity(n);

    // For each length from 1 up to n, take the corresponding prefix
    for i in 1..=n {
        // s[0..i] is the prefix of length i
        result.push(s[0..i].to_vec());
    }

    result
}

